from datetime import datetime, timedelta


def billing_date(iso_utc, offset_hours):
    """Return the customer's local calendar date for a UTC timestamp."""
    ts = datetime.fromisoformat(iso_utc)
    local = ts + timedelta(hours=offset_hours)
    return ts.date()


def due_date(issued, net_days):
    return issued + timedelta(days=net_days)

